"objective": {
"factors": [
"机制完备性（覆盖摩擦、能量源丧失、风切变、流出阻塞等核心物理过程的比例）",
"量化准确性（每个机制对应的典型衰减速率数值或公式与文献共识的偏差）",
"主导性论证强度（通过量级对比或敏感性分析明确区分主导与非主导机制的可判定性）",
"异质性解释力（对强台风、飓风、热带风暴等不同强度类别衰减速率差异及其成因的解释覆盖率）",
"不确定性界定清晰度（明确标识出数据争议大、依赖具体环境或模型假设的黑盒变量范围）"
],
"composition": "M_completeness * Q_accuracy * D_dominance * H_heterogeneity * U_clarity (乘积关系：任一要素缺失或错误导致整体答案无效)",
"rationale": "该问题要求从物理机制到量化结果的完整因果链条，任何单一维度的缺失（如只有定性无定量，或只有平均数无差异分析）都会破坏解释的完整性和科学性，因此各要素缺一不可。"
},
"dimensions": [
{
"id": "D1",
"name": "物理机制谱系",
"scope": "涵盖所有导致登陆后减弱的物理过程（表面摩擦、潜热输入中断、垂直风切变增强、环境流出层阻塞等）的定义与作用逻辑。"
},
{
"id": "D2",
"name": "量化衰减动力学",
"scope": "对应各物理机制的典型衰减速率数值（如每小时减弱多少节）、经验公式或参数化方案，以及时间尺度特征。"
},
{
"id": "D3",
"name": "主导效应判别",
"scope": "基于量级估算或敏感性分析，确定在典型情境下哪个机制是减弱的主导项，并排除次要因素的干扰。"
},
{
"id": "D4",
"name": "强度依赖性差异",
"scope": "分析初始强度（强台风vs热带风暴等）、结构特征（眼墙半径、对流组织）如何调制衰减速率，解释不同类别气旋的差异。"
},
{
"id": "D5",
"name": "环境调制因素",
"scope": "识别外部环境变量（如陆面粗糙度分布、背景风场、海陆温差）如何改变上述机制的权重和衰减速率。"
},
{
"id": "D6",
"name": "认知边界与黑盒",
"scope": "明确列出当前科学界存在争议、数据不足或高度依赖特定案例的不确定性因素（如精确的摩擦系数值、复杂地形下的局地效应）。"
}
]
}

